from pathlib import Path
import json,hashlib,csv,html

ROOT=Path(__file__).resolve().parents[1]
names=['6241 Léger','6280 Somerled NDG','HARMONY MOVERS']
cases=[]
for name in names:
    base=ROOT/name
    records=[]
    for f in sorted(base.rglob('*')):
        if not f.is_file() or any(p in ['99_Travail_et_collecte','09_Index_et_tracabilite'] for p in f.parts):continue
        if f.name in ['tableau-de-bord.json','index.html']:continue
        rel=f.relative_to(ROOT).as_posix()
        records.append({'name':f.name,'path':rel,'category':f.relative_to(base).parts[0],'bytes':f.stat().st_size,'sha256':hashlib.sha256(f.read_bytes()).hexdigest()})
    intros=[r for r in records if r['category'] in ['00_Lire_en_premier','01_Synthese_et_chronologie'] and r['name'].endswith('.md')]
    if name==names[0]:intros.insert(0,{'path':name+'/00_Lire_en_premier/index.html','name':'Tableau de bord · textes et chronologie'})
    remise=base/'12_Remise_Dufourd_2026-10-21/LIRE-EN-PREMIER.md'
    if name=='HARMONY MOVERS' and remise.is_file():
        intros.insert(0,{'path':remise.relative_to(ROOT).as_posix(),'name':'Remise Dufourd · réponses, pièces et téléchargements'})
    cases.append({'name':name,'files':records,'distinct':len(set(r['sha256'] for r in records)),'guides':intros})
(ROOT/'documentation').mkdir(exist_ok=True)
(ROOT/'documentation/INDEX-TROIS-DOSSIERS.json').write_text(json.dumps(cases,ensure_ascii=False,indent=2),encoding='utf-8')
template='''<!DOCTYPE html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Dossiers pour l’avocat</title><style>
:root{--ink:#173542;--muted:#526c77;--teal:#087c7f;--paper:#f2f5f3;--line:#d3dfdf}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--paper);font:15px/1.55 'Segoe UI',Arial,sans-serif}header{background:var(--ink);color:#fff;padding:48px max(6vw,24px) 44px}header small{letter-spacing:2px;color:#b3d6d0}h1{font-size:42px;letter-spacing:-1px;margin:12px 0}header p{max-width:780px;color:#ccdbdf}main{max-width:1440px;margin:auto;padding:32px max(4vw,24px)}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card,.panel{background:white;border:1px solid var(--line);padding:24px;border-radius:12px;margin-bottom:26px}.card h2{font-size:23px;margin:8px 0}.num{font-size:12px;letter-spacing:1px;color:var(--teal)}.meta{color:var(--muted);font-size:13px}.card ul{padding-left:18px}.card li{padding:5px 0}a{color:var(--teal);text-underline-offset:3px}button{background:var(--teal);color:white;border:0;border-radius:6px;padding:10px 16px;font:inherit;cursor:pointer}input,select{border:1px solid #a9bdc2;border-radius:6px;padding:12px;font:inherit;background:white;color:var(--ink)}input{flex:1;min-width:220px}.tools{display:flex;flex-wrap:wrap;gap:12px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;padding:13px 12px;border-bottom:1px solid var(--line);vertical-align:top}th{font-size:11px;text-transform:uppercase;color:var(--muted);white-space:nowrap}td:first-child{max-width:600px;overflow-wrap:anywhere}.path{font-size:11px;color:var(--muted);margin-top:5px}.note{border-left:3px solid #c99051;padding:12px 18px;background:#faf1e5}.footer{font-size:12px;color:var(--muted);margin:20px 0}.pill{display:inline-block;border-radius:12px;padding:3px 9px;background:#e9f3f0;color:var(--teal);font-size:11px}@media(max-width:850px){.cards{grid-template-columns:1fr}h1{font-size:32px}}@media print{.tools,button{display:none}header{background:white;color:black;padding:10px}header p{color:#333}.cards{display:block}.card{break-inside:avoid}main{padding:0}}
</style></head><body><header><small>ESPACE DE TRAVAIL · 21 OCTOBRE 2026</small><h1>Dossiers pour l’avocat</h1><p>Trois dossiers distincts, une entrée commune. Retrouvez les synthèses, les courriels, les factures et les pièces classées dans votre espace OneDrive.</p></header><main><div id="cards" class="cards"></div><div class="panel"><h2>Retrouver une pièce</h2><p class="meta">Recherche dans les noms et chemins des trois dossiers. Le tableau de bord Léger permet aussi de chercher dans les textes PDF et l’OCR.</p><div class="tools"><input id="query" aria-label="Rechercher une pièce" placeholder="Facture, bail, avocat, saisie…"><select id="case" aria-label="Choisir le dossier"><option value="">Tous les dossiers</option></select><select id="category" aria-label="Choisir la catégorie"><option value="">Toutes les catégories</option></select><button id="export">Exporter la sélection CSV</button></div><p id="count" class="meta" aria-live="polite"></p><div class="scroll"><table><thead><tr><th>Pièce</th><th>Dossier</th><th>Catégorie</th><th>Taille</th></tr></thead><tbody id="rows"></tbody></table></div></div><div class="note"><strong>Comment lire ces dossiers</strong><p>Les originaux, les déclarations et les analyses sont identifiés par leur provenance. Les doublons et les versions d’une facture ne s’additionnent pas. Une extraction OCR reste à contrôler sur la pièce originale. Les documents à obtenir et les vérifications ouvertes figurent dans les synthèses de chaque dossier.</p></div><p class="footer">Cet index ouvre les fichiers locaux. La synchronisation OneDrive et la publication GitHub sont des états distincts de ce classement. Dépôt créé : <a href="https://github.com/takatakca/assurance-6241">takatakca/assurance-6241</a>.</p></main><script>
const CASES=/*DATA*/;
const $=id=>document.getElementById(id),el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n},norm=s=>String(s).normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase();
const href=p=>p.split('/').map(encodeURIComponent).join('/');
let all=[],selected=[];
CASES.forEach((c,i)=>{all.push(...c.files.map(f=>({...f,case:c.name})));$('case').append(new Option(c.name,c.name));const card=el('section');card.className='card';const n=el('div','DOSSIER 0'+(i+1));n.className='num';const title=el('h2',c.name),meta=el('p',c.files.length+' fichiers · '+c.distinct+' contenus distincts');meta.className='meta';card.append(n,title,meta);const list=el('ul');c.guides.forEach(g=>{const li=el('li'),a=el('a',g.name.replace(/\\.md$/,''));a.href=href(g.path);li.append(a);list.append(li)});card.append(list);const b=el('button','Voir les pièces');b.onclick=()=>{$('case').value=c.name;categories();render();$('query').scrollIntoView({behavior:'smooth',block:'center'})};card.append(b);$('cards').append(card)});
function categories(){const current=$('category').value;$('category').replaceChildren(new Option('Toutes les catégories',''));[...new Set(all.filter(f=>!$('case').value||f.case===$('case').value).map(f=>f.category))].sort().forEach(c=>$('category').append(new Option(c.replaceAll('_',' '),c)));if([...$('category').options].some(o=>o.value===current))$('category').value=current}
function render(){const q=norm($('query').value);selected=all.filter(f=>(!$('case').value||f.case===$('case').value)&&(!$('category').value||f.category===$('category').value)&&norm(f.path).includes(q));$('count').textContent=selected.length+' fichiers trouvés';const frag=document.createDocumentFragment();selected.forEach(f=>{const tr=el('tr'),td=el('td'),a=el('a',f.name);a.href=href(f.path);a.target='_blank';a.rel='noopener';td.append(a);const p=el('div',f.path);p.className='path';td.append(p);tr.append(td,el('td',f.case),el('td',f.category.replaceAll('_',' ')),el('td',new Intl.NumberFormat('fr-CA',{maximumFractionDigits:1}).format(f.bytes/1024)+' Ko'));frag.append(tr)});$('rows').replaceChildren(frag)}
$('query').oninput=render;$('category').onchange=render;$('case').onchange=()=>{categories();render()};$('export').onclick=()=>{const escape=v=>'"'+(/^[=+@-]/.test(String(v))?"'":'')+String(v).replaceAll('"','""')+'"';const out=['Dossier;Fichier;Chemin;Empreinte SHA256',...selected.map(f=>[f.case,f.name,f.path,f.sha256].map(escape).join(';'))].join('\\r\\n');const a=el('a');a.href=URL.createObjectURL(new Blob(['\\ufeff'+out],{type:'text/csv;charset=utf-8'}));a.download='pieces-selectionnees.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};categories();render();
</script></body></html>'''
(ROOT/'OUVRIR-LES-DOSSIERS.html').write_text(template.replace('/*DATA*/',json.dumps(cases,ensure_ascii=False).replace('<','\\u003c')),encoding='utf-8')
print(json.dumps([{'dossier':c['name'],'fichiers':len(c['files']),'distincts':c['distinct']} for c in cases],ensure_ascii=False))
